test('multi-location shifts and clocks cannot overlap; closing a clock keeps the time at its original location',async()=>{const app=await fixture();try{
 const sharedRecord=await app.user('Shared','user',[app.office.session.locationId,app.other.id]),shared=await app.login('Shared');await roster(app,app.office,'shifts','POST',shift({userId:sharedRecord.id}));await app.request(app.office,'/api/session/company','PUT',{companyId:app.company.id});assert.equal((await roster(app,app.office,'shifts','POST',shift({userId:sharedRecord.id}))).status,409);
 await app.request(app.office,'/api/session/company','PUT',{companyId:'default'});const activeShift=await publishClockShift(app,sharedRecord.id);const begun=await clock(app,shared,'in',{shiftId:activeShift});await app.request(shared,'/api/session/company','PUT',{companyId:app.company.id});assert.equal((await clock(app,shared,'in')).status,409);assert.equal((await roster(app,shared)).data.clock.locationId,app.member.session.locationId);app.advance(3600000);assert.equal((await clock(app,shared,'out',{entryId:begun.data.id})).status,200);assert.equal((await roster(app,shared)).data.timesheets.length,0);await app.request(shared,'/api/session/company','PUT',{companyId:'default'});assert.equal((await roster(app,shared)).data.timesheets.length,1);
 }finally{await app.close();}});
test('roster date math handles Melbourne nights and DST and missing forecasts stay unknown',()=>{
 const spring=rosterModel.interval({date:'2026-10-03',start:'22:00',end:'06:00',overnight:true,breakMinutes:30}),autumn=rosterModel.interval({date:'2026-04-04',start:'22:00',end:'06:00',overnight:true,breakMinutes:30});assert.equal(spring.paidSeconds,6.5*3600);assert.equal(autumn.paidSeconds,8.5*3600);assert.throws(()=>rosterModel.instant('2026-10-04','02:30'));assert.throws(()=>rosterModel.instant('2026-04-05','02:30'));for(const day of ['2026-13-01','2026-02-30','bad'])assert.throws(()=>rosterModel.date(day));const projection=rosterModel.project([],'2026-10-19',Date.parse('2026-10-19T09:00:00Z'));assert.equal(projection.projectedSalesCents,null);assert.equal(projection.weeksRecorded,0);
});
