 await roster(app,app.office,'shifts','POST',shift({userId:app.memberRecord.id}));assert.equal((await roster(app,app.office)).data.summary.plannedCostCents,0);const noRole=await app.role('No roster',['home.view']),none=await app.assign(app.memberRecord,noRole);assert.equal((await roster(app,none)).status,403);assert.equal((await app.request(none,'/rostering')).redirect,'/home');assert.equal((await app.request(null,'/rostering')).redirect,'/login');
