test('rostering upgrades built-in and full network levels while keeping customised roles unchanged',async()=>{const dir=await fs.mkdtemp(path.join(os.tmpdir(),'roster-roles-'));try{
 const old=model.defaults.map(role=>({...role,permissions:role.permissions.filter(key=>!model.rosteringKeys.includes(key))})),custom={id:'custom',scope:'default',name:'Custom',level:5,permissions:['home.view']},full={...old.find(role=>role.id==='admin'),id:'custom-full',name:'Network owners'};await fs.writeFile(path.join(dir,'permission-levels.json'),JSON.stringify({revision:4,communicationsVersion:1,knowledgeVersion:1,levels:[...old,custom,full]}));const result=await levels.createStore(dir).read();assert.equal(result.rosteringVersion,1);assert.equal(result.revision,4);assert.deepEqual(result.levels.find(role=>role.id==='custom').permissions,custom.permissions);for(const role of model.defaults)assert.deepEqual(result.levels.find(item=>item.id===role.id).permissions,role.permissions);assert.deepEqual(result.levels.find(role=>role.id==='custom-full').permissions,model.keys);
 }finally{await fs.rm(dir,{recursive:true,force:true});}});
