test('daily rosters include overnight carryovers with published, user and location access rules',async()=>{
 const app=await fixture();try{
  const prior={weekStart:'2026-10-12',date:'2026-10-18',start:'22:00',end:'06:00',overnight:true,breakMinutes:30};
  const created=await roster(app,app.office,'shifts','POST',shift({...prior,userId:app.memberRecord.id}));assert.equal(created.status,201);
  await roster(app,app.office,'shifts','POST',shift({...prior,revision:1,userId:null}));
  let dashboard=(await roster(app,app.office)).data;assert.equal(dashboard.roster.shifts.length,0);assert.equal(dashboard.roster.carryoverShifts.length,2);assert.equal(dashboard.roster.carryoverShifts[0].paidSeconds,27000);
  assert.equal((await roster(app,app.member)).data.roster.carryoverShifts.length,0,'Previous-week drafts stay private');
  await roster(app,app.office,'publish','POST',{weekStart:'2026-10-12',revision:2});
  dashboard=(await roster(app,app.member)).data;assert.equal(dashboard.roster.carryoverShifts.length,1);assert.equal(dashboard.roster.carryoverShifts[0].userId,app.memberRecord.id);assert.ok(!('costCents' in dashboard.roster.carryoverShifts[0]));assert.ok(!('rateCents' in dashboard.roster.carryoverShifts[0]));
  await roster(app,app.office,'shifts/'+created.data.shift.id,'PUT',shift({...prior,revision:3,userId:app.memberRecord.id,end:'07:00'}));
  assert.equal((await roster(app,app.office)).data.roster.carryoverShifts.find(item=>item.id===created.data.shift.id).end,'07:00');assert.equal((await roster(app,app.member)).data.roster.carryoverShifts[0].end,'06:00','Unpublished carryover edits stay private');
  assert.equal((await roster(app,app.franchisee)).data.roster.carryoverShifts.length,2);assert.equal((await roster(app,app.outside)).data.roster.carryoverShifts.length,0);
  const other=(await roster(app,app.office,'dashboard?week=2026-10-26')).data;assert.equal(other.roster.carryoverShifts.length,0);
 }finally{await app.close();}
});

test('compact roster time inputs preserve midday, midnight and 24-hour values',()=>{
 for(const [input,expected]of [['9a','09:00'],['9:30a','09:30'],['9:30 AM','09:30'],['530p','17:30'],['12p','12:00'],['12:00a','00:00'],['00:00','00:00'],['23:59','23:59'],['2359','23:59']])assert.equal(rosterModel.parseTimeInput(input),expected,input);
 for(const input of ['',null,'24:00','13p','0a','9:60a','99:00','9:3','7:30x'])assert.equal(rosterModel.parseTimeInput(input),null,String(input));
 for(let minute=0;minute<1440;minute++){const time=String(Math.floor(minute/60)).padStart(2,'0')+':'+String(minute%60).padStart(2,'0');assert.equal(rosterModel.parseTimeInput(rosterModel.formatTimeInput(time)),time);}
 assert.equal(rosterModel.formatTimeInput('00:00'),'12:00a');assert.equal(rosterModel.formatTimeInput('12:00'),'12:00p');assert.equal(rosterModel.formatTimeInput('19:05'),'7:05p');
});
test('phone-derived clock PINs are set through Users, never returned as credentials, and required for every action',async()=>{const app=await fixture();try{
 const noPin=(await app.request(app.office,'/api/accounts','POST',{username:'No PIN',password:'member-test-password',role:'user',locationId:app.office.session.locationId})).data,worker=await app.login('No PIN');assert.equal(noPin.clockPinSet,false);assert.equal((await roster(app,worker,'clock-status')).data.pinSet,false);
 assert.equal((await app.request(app.office,'/api/accounts/'+noPin.id,'PUT',{username:noPin.username,role:'user',phoneNumber:'123'})).status,400);
 assert.equal((await app.request(app.member,'/api/accounts/'+noPin.id,'PUT',{username:noPin.username,role:'user',phoneNumber:'0400001234'})).status,403);
 assert.equal((await app.request(app.franchisee,'/api/accounts/'+app.office.session.id,'PUT',{username:'Office',role:'admin',phoneNumber:'0400001234'})).status,403);
 const saved=await app.request(app.office,'/api/accounts/'+noPin.id,'PUT',{username:noPin.username,role:'user',phoneNumber:'0400000007'});assert.equal(saved.status,200);assert.equal(saved.data.clockPinSet,true);assert.ok(!('clockPin'in saved.data));assert.ok(!('hash'in saved.data));
 const shiftId=await publishClockShift(app,noPin.id);assert.equal((await clock(app,worker,'in',{shiftId,pin:undefined})).status,401);assert.equal((await clock(app,worker,'in',{shiftId,pin:7})).status,401);assert.equal((await clock(app,worker,'in',{shiftId,pin:'0007'})).status,200);
 const started=(await roster(app,worker,'clock-status')).data.entry;app.advance(3600000);
 for(const [action,extra]of [['break-start',{breakType:'paid'}],['break-end',{}],['break-start',{breakType:'unpaid'}],['break-end',{}],['out',{}]]){const body={entryId:started.id,...extra};assert.equal((await clock(app,worker,action,{...body,pin:'9999'})).status,401);assert.equal((await clock(app,worker,action,{...body,pin:'0007'})).status,200);app.advance(30*60000);}
 const accounts=JSON.parse(await fs.readFile(path.join(app.dir,'accounts.json'),'utf8')),stored=accounts.find(a=>a.id===noPin.id);assert.equal(stored.clockPin.hash.length,128);assert.notEqual(stored.clockPin.salt,accounts.find(a=>a.id===app.memberRecord.id).clockPin.salt);assert.ok(!JSON.stringify((await roster(app,worker)).data).includes('0007'));assert.ok(!JSON.stringify((await app.request(app.office,'/api/accounts')).data).includes(stored.clockPin.hash));
 const reset=await app.request(app.office,'/api/accounts/'+noPin.id,'PUT',{username:noPin.username,role:'user',phoneNumber:'0400000088'});assert.equal(reset.status,200);assert.equal((await clock(app,worker,'in',{shiftId,pin:'0007'})).status,401);
 }finally{await app.close();}});
test('early starts require staff and a different eligible manager PIN, on the scheduled local day, with an approval audit',async()=>{const app=await fixture();try{
 app.advance(-20*3600000);const created=await roster(app,app.office,'shifts','POST',shift({userId:app.memberRecord.id})),shiftId=created.data.shift.id;await roster(app,app.office,'publish','POST',{weekStart:'2026-10-19',revision:1});let state=(await roster(app,app.member,'clock-status')).data;assert.equal(state.phase,'early-start');assert.ok(state.hasApprover);assert.ok(!('managers'in state));
 const other=await app.user('Other manager','franchisee',[app.other.id]),approval={shiftId,managerPin:'9876'};
 app.advance(-60000);assert.equal((await clock(app,app.member,'in',approval)).status,409);app.advance(60000);
 assert.equal((await clock(app,app.member,'in',{...approval,shiftId:undefined})).status,409);
 assert.equal((await clock(app,app.member,'in',{shiftId})).status,401);
 assert.equal((await clock(app,app.member,'in',{...approval,managerPin:other.phoneNumber.slice(-4)})).status,401);
 assert.equal((await clock(app,app.member,'in',{...approval,managerPin:'0123'})).status,401);
 assert.equal((await clock(app,app.member,'in',{...approval,managerPin:'0000'})).status,401);assert.equal((await roster(app,app.member,'clock-status')).data.entry,null);
 const requestId=crypto.randomUUID(),started=await clock(app,app.member,'in',{...approval,requestId});assert.equal(started.status,200,JSON.stringify(started.data));assert.equal(started.data.startAt,'2026-10-18T13:00:00.000Z');assert.equal(started.data.earlyStartApproval.userId,app.office.session.id);assert.equal(started.data.earlyStartApproval.scheduledStartAt,'2026-10-18T22:00:00.000Z');assert.equal(started.data.audit[0].reason,'Early start approved by Office');assert.ok(!JSON.stringify(started.data).includes('9876'));
 assert.equal((await clock(app,app.member,'in',{...approval,requestId,managerPin:undefined})).data.id,started.data.id,'retry does not require a second approval or record another punch');
 const raw=JSON.parse(await fs.readFile(path.join(app.dir,'rostering.json'),'utf8'));assert.equal(raw.entries.length,1);assert.equal(raw.entries[0].audit.length,1);assert.ok(!JSON.stringify(raw).includes('managerPin'));
 }finally{await app.close();}});
