 const legacy=(await app.request(app.office,'/api/accounts','POST',{username:'Legacy',password:'member-test-password',role:'user',locationId:app.office.session.locationId})).data,accountFile=path.join(app.dir,'accounts.json'),imported=JSON.parse(await fs.readFile(accountFile,'utf8'));imported.find(a=>a.id===legacy.id).clockPin=imported.find(a=>a.id===app.memberRecord.id).clockPin;await fs.writeFile(accountFile,JSON.stringify(imported));assert.equal((await app.request(app.office,'/api/accounts/'+app.memberRecord.id,'PUT',{username:'Member',role:'user',phoneNumber:'0400000123'})).status,200,'an inactive legacy PIN without a phone does not reserve an ending');const legacyActor=await app.login('Legacy');assert.equal((await roster(app,legacyActor,'clock-status')).data.pinSet,false);assert.equal((await clock(app,legacyActor,'in',{pin:'0123'})).status,409);
